# generated by Gemini 3 Pro
import numpy as np
import matplotlib.pyplot as plt
from scipy.fft import fft, fftfreq, fftshift
from scipy.signal.windows import hann


def plot_signal_analysis(
    signal: np.ndarray,
    fs: float,
    title: str = "Signal Analysis",
    zoom_usec: float = 100.0,
    carrier_freq: float = None,
    xlim_freq: list = None,
    figsize: tuple = (12, 8),
):
    """
    時間領域の波形と周波数領域のスペクトルを併せて描画する。

    Args:
        signal (np.ndarray): 入力信号データ（実数または複素数）
        fs (float): サンプリング周波数 [Hz]
        title (str): グラフのタイトル
        zoom_usec (float): 時間軸の表示範囲 [マイクロ秒] (既定値: 100μs)
        carrier_freq (float, optional): 搬送波周波数のマーカー位置 [Hz]
        xlim_freq (list, optional): 周波数軸の表示範囲
        figsize (tuple): 図のサイズ
    """

    # --- データの準備 ---
    N = len(signal)
    t = np.arange(N) / fs

    # 複素信号(IQ)と実信号で処理を分岐する
    is_complex = np.iscomplexobj(signal)

    # --- 1. 時間軸プロット (Time Domain) ---
    fig, axes = plt.subplots(2, 1, figsize=figsize, constrained_layout=True)

    ax_time = axes[0]

    # 表示範囲のサンプル数を算出する
    zoom_samples = int(zoom_usec * 1e-6 * fs)
    if zoom_samples > N:
        zoom_samples = N
    if zoom_samples < 2:
        zoom_samples = N  # 表示範囲が 2 サンプル未満の場合は全区間を表示する

    # 時間軸をマイクロ秒単位に変換してプロット
    t_zoom = t[:zoom_samples] * 1e6
    sig_zoom = signal[:zoom_samples]

    if is_complex:
        ax_time.plot(
            t_zoom, sig_zoom.real, label="I (Real)", color="#1f77b4", alpha=0.8
        )
        ax_time.plot(
            t_zoom, sig_zoom.imag, label="Q (Imag)", color="#ff7f0e", alpha=0.8
        )
        ax_time.set_ylabel("Amplitude (I/Q)")
        ax_time.legend(loc="upper right")
    else:
        ax_time.plot(t_zoom, sig_zoom, color="#2ca02c")
        ax_time.set_ylabel("Amplitude")

    ax_time.set_title(f"{title} - Time Domain")
    ax_time.set_xlabel("Time [μs]")
    ax_time.grid(True, linestyle="--", alpha=0.6)

    # --- 2. 周波数軸プロット (Frequency Domain) ---
    ax_freq = axes[1]

    # FFT
    n_fft = min(65536, N)
    window = hann(n_fft)
    # データ長が FFT 長に満たない場合はゼロ詰めする
    if len(signal) < n_fft:
        sig_fft_in = np.pad(signal, (0, n_fft - len(signal))) * window
    else:
        sig_fft_in = signal[:n_fft] * window

    yf = fftshift(fft(sig_fft_in))
    xf = fftshift(fftfreq(n_fft, 1 / fs))
    mag_db = 20 * np.log10(np.abs(yf) / n_fft + 1e-12)

    # プロット
    ax_freq.plot(xf / 1e3, mag_db, color="#9467bd", linewidth=1.2)

    # 搬送波マーカー
    if carrier_freq is not None:
        ax_freq.axvline(x=carrier_freq / 1e3, color="r", linestyle=":", label="Carrier")
        if not is_complex:
            ax_freq.axvline(x=-carrier_freq / 1e3, color="r", linestyle=":", alpha=0.5)
        ax_freq.legend()

    # 表示範囲の設定
    if xlim_freq is not None:
        ax_freq.set_xlim(xlim_freq)
    else:
        # 既定値: 全帯域
        ax_freq.set_xlim([xf.min() / 1e3, xf.max() / 1e3])

    ax_freq.set_title("Frequency Domain (Spectrum)")
    ax_freq.set_xlabel("Frequency [kHz]")
    ax_freq.set_ylabel("Magnitude [dB]")
    ax_freq.grid(True, linestyle="--", alpha=0.6)

    plt.show()


# --- 入出力比較(make run の解析グラフ) ---------------------------------------


def split_channels(data: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """入力形状 (N,) / (N, 1) / (N, 2) によらず L, R の 2 系列を返す。"""
    if data.ndim == 1:
        return data, data
    if data.ndim == 2 and data.shape[1] == 2:
        return data[:, 0], data[:, 1]
    if data.ndim == 2 and data.shape[1] == 1:
        flat = data.flatten()
        return flat, flat
    raise ValueError(f"Unexpected data shape: {data.shape}")


def estimate_lag(in_ch: np.ndarray, out_ch: np.ndarray) -> int:
    """相互相関により、入力に対する出力の遅延 [サンプル] を推定する。"""
    m = min(len(in_ch), len(out_ch))
    seg = slice(m // 4, m // 4 + min(40000, m // 2))
    x = in_ch[seg] - np.mean(in_ch[seg])
    y = out_ch[seg] - np.mean(out_ch[seg])
    xc = np.correlate(y, x, mode="full")
    return int(np.argmax(np.abs(xc)) - (len(x) - 1))


def gain_match(in_ch: np.ndarray, out_ch: np.ndarray, lag: int) -> float:
    """遅延整列した全区間の RMS 比から、出力に乗じる振幅補正係数を求める。

    受信機の周波数弁別器は出力を最大周波数偏移で正規化していないため、
    出力は入力に対して一定の利得(約 −14.7 dB)をもつ。時間波形と PSD の
    双方に同一の係数を適用し、入出力を同一スケールで比較できるようにする。
    """
    if lag >= 0:
        i, o = in_ch, out_ch[lag:]
    else:
        i, o = in_ch[-lag:], out_ch
    n = min(len(i), len(o))
    ri, ro = np.sqrt(np.mean(i[:n] ** 2)), np.sqrt(np.mean(o[:n] ** 2))
    return ri / ro if ro > 0 else 1.0


def plot_stereo_analysis(
    audio_in: np.ndarray,
    audio_out: np.ndarray,
    fs: float,
    filename: str,
    n_display: int = 1000,
    f_max: float = 15_000.0,
):
    """入力と復調出力を L/R ごとに比較する解析グラフを生成し、保存する。

    上段は遅延整列・振幅補正した時間波形の重ね合わせと残差(In−Out)、
    下段は入出力のパワースペクトル密度。遅延は L チャネルから推定し、
    両チャネルに共通に適用する。振幅補正係数はチャネルごとに求める(いずれも表示専用)。

    Args:
        audio_in: 入力音声 (N,) または (N, 2)
        audio_out: 復調音声 (N,) または (N, 2)
        fs: サンプリング周波数 [Hz]
        filename: 保存先のパス
        n_display: 時間波形として表示するサンプル数
        f_max: PSD の表示上限周波数 [Hz]

    Returns:
        matplotlib.figure.Figure: 生成した図
    """
    in_l, in_r = split_channels(audio_in)
    out_l, out_r = split_channels(audio_out)

    lag = estimate_lag(in_l, out_l)  # 群遅延 [サンプル]
    start = min(len(in_l) // 4, max(0, len(in_l) - n_display - abs(lag)))
    t_axis = np.arange(n_display) / fs * 1000
    delay_ms = lag / fs * 1000

    channels = [
        ("Left", "L", in_l, out_l, "blue", "cyan"),
        ("Right", "R", in_r, out_r, "red", "orange"),
    ]

    fig, axes = plt.subplots(2, 2, figsize=(14, 10))
    for col, (name, ch, x_in, x_out, c_in, c_out) in enumerate(channels):
        gain = gain_match(x_in, x_out, lag)
        x_out = x_out * gain

        # --- 上段: 時間波形(遅延整列・振幅補正)+ 残差 ---
        i = x_in[start : start + n_display]
        o = x_out[start + lag : start + lag + n_display]
        ax = axes[0, col]
        ax.plot(t_axis, i, label=f"In ({ch})", color=c_in, alpha=0.5)
        ax.plot(t_axis, o, label=f"Out ({ch})", color=c_out, alpha=0.8, linestyle="--")
        ax.plot(t_axis, i - o, label="In−Out", color="gray", alpha=0.6, lw=0.8)
        ax.set_title(f"{name} Channel (Time Domain, delay {delay_ms:.2f}ms aligned)")
        ax.set_xlabel("Time [ms]")
        ax.set_ylabel(
            "Amplitude"
        )  # 直流成分を持たない信号のため 0 を中心に正負へ振れる
        ax.legend(loc="upper right")
        ax.grid(True, alpha=0.3)

        # --- 下段: パワースペクトル密度 ---
        ax = axes[1, col]
        ax.psd(x_in, Fs=fs, NFFT=1024, color=c_in, label=f"In ({ch})")
        ax.psd(
            x_out, Fs=fs, NFFT=1024, color=c_out, label=f"Out ({ch})", linestyle="--"
        )
        ax.set_title(
            f"{name} Channel (PSD, output gain-matched {20 * np.log10(gain):+.1f} dB)"
        )
        ax.set_xlim(0, f_max)
        ax.legend(loc="upper right")

    fig.tight_layout()
    fig.savefig(filename)
    return fig
